const test=require('node:test'),assert=require('node:assert/strict');
const model=import('../playground-model.js');
function fixture(){return {id:'board',revision:1,population:6,instances:[{instanceId:'a',cardId:'home',cardRevision:1,q:0,r:0,rotation:0},{instanceId:'b',cardId:'garden',cardRevision:1,q:1,r:0,rotation:0}],cards:{'home@1':{ports:[{id:'gate',verified:true,kind:'pedestrian',x:43,y:0,z:0,direction:{x:1,z:0}}],capabilities:{housing:6}},'garden@1':{ports:[{id:'gate',verified:true,kind:'footpath',x:-40,y:0,z:0,direction:{x:-1,z:0}}],capabilities:{garden:12}}}};}
function evidence(c){return {signature:c.signature,verified:true,traversable:true,obstructionFree:true,terrainChecked:true,kind:'pedestrian',path:[c.access.a,c.access.b].map(({x,y,z})=>({x,y,z}))};}
test('proximity is only a candidate; explicit traversal evidence enables economy',async()=>{const {inspectConnections,simulationBoard}=await model,b=fixture();let r=inspectConnections(b);assert.equal(r.connections.length,0);assert.equal(r.candidates.length,1);assert.equal(r.warnings.length,2);assert.equal(simulationBoard(b).connections.length,0);r=inspectConnections(b,{verifyJoin:evidence});assert.equal(r.connections.length,1);assert.equal(r.warnings.length,0);assert.equal(simulationBoard(b,{verifyJoin:evidence}).connections.length,1);});
test('unverified, utility, backwards and missing-direction ports cannot grant access',async()=>{const {inspectConnections}=await model;for(const patch of [{verified:undefined},{verified:false},{kind:'power'},{kind:'access',mode:'water'},{direction:{x:1,z:0}},{direction:null},{id:''},{y:NaN}]){const b=fixture();Object.assign(b.cards['garden@1'].ports[0],patch);assert.equal(inspectConnections(b,{verifyJoin:evidence}).connections.length,0,JSON.stringify(patch));}});
test('obstructed, unchecked, stale and too-steep joining evidence stays non-economic',async()=>{const {inspectConnections}=await model;for(const patch of [{obstructionFree:false},{terrainChecked:false},{traversable:false},{verified:false},{signature:'old'},{path:[]},{kind:'utility'}])assert.equal(inspectConnections(fixture(),{verifyJoin:c=>({...evidence(c),...patch})}).connections.length,0);const b=fixture();assert.equal(inspectConnections(b,{verifyJoin:c=>({...evidence(c),path:[c.access.a,{x:44,y:3,z:0},c.access.b]})}).connections.length,0);assert.equal(inspectConnections(b,{verifyJoin:()=>{throw Error('No terrain');}}).connections.length,0);});
test('persisted evidence is invalidated by movement, elevation and card revision changes',async()=>{const {inspectConnections}=await model,b=fixture();b.joinEvidence=[evidence(inspectConnections(b).candidates[0])];assert.equal(inspectConnections(b).connections.length,1);for(const change of [c=>c.revision++,c=>c.id="other-board",c=>c.instances[1].elevation=.1,c=>c.instances[1].rotation=1,c=>{c.cards['garden@2']=c.cards['garden@1'];c.instances[1].cardRevision=2;},c=>c.cards['garden@1'].ports[0].x+=.2]){const copy=structuredClone(b);change(copy);assert.equal(inspectConnections(copy).connections.length,0);}});
test('rotated outward directions transform with the whole instance',async()=>{const {inspectConnections}=await model,b=fixture();b.instances[1].rotation=3;b.cards['garden@1'].ports[0].x=40;b.cards['garden@1'].ports[0].direction.x=1;assert.equal(inspectConnections(b,{verifyJoin:evidence}).connections.length,1);});
